<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>{{ $kind==='invoice'?'Invoice':'Packing slip' }} · {{ $order->reference }}</title>@vite(['resources/css/app.css'])</head><body class="document-body"><div class="document-toolbar"><button class="button" onclick="window.print()">Print {{ $kind==='invoice'?'invoice':'packing slip' }}</button><a href="/admin/orders/{{ $order->id }}">Back to order ↗</a></div><article class="print-document"><header><div><h1>{{ $store['brand']??'Clovic' }}</h1><p>{{ $store['business_address']??'' }}<br>{{ $store['email']??'' }} · {{ $store['phone']??'' }}</p></div><div><span class="eyebrow">{{ $kind==='invoice'?'ORDER INVOICE':'PACKING SLIP' }}</span><h2>{{ $order->reference }}</h2><p>{{ $order->created_at->format('d M Y') }}</p></div></header><div class="document-address"><h3>Deliver to</h3><p>{{ $order->name }}<br>{{ $order->phone }}<br>{{ $order->address }}<br>{{ $order->district }}</p></div><table><thead><tr><th>Item / SKU</th><th>Size / color</th><th>Quantity</th>@if($kind==='invoice')<th>Unit price</th><th>Discount</th><th>Line total</th>@endif</tr></thead><tbody>@foreach($order->items as $item)<tr><td>{{ $item->product_name }}<small>{{ $item->sku }}</small></td><td>{{ $item->size }} / {{ $item->color }}</td><td>{{ $item->quantity }}</td>@if($kind==='invoice')<td>{{ \App\Services\Settings::money($item->unit_price) }}</td><td>{{ \App\Services\Settings::money($item->discount) }}</td><td>{{ \App\Services\Settings::money($item->unit_price*$item->quantity-$item->discount) }}</td>@endif</tr>@endforeach</tbody></table>@if($kind==='invoice')<div class="document-totals"><div class="summary-row"><span>Subtotal</span><span>{{ \App\Services\Settings::money($order->subtotal) }}</span></div><div class="summary-row"><span>Delivery</span><span>{{ \App\Services\Settings::money($order->delivery) }}</span></div><div class="summary-row"><span>Discount</span><span>−{{ \App\Services\Settings::money($order->discount) }}</span></div><div class="summary-row total"><strong>Total</strong><strong>{{ \App\Services\Settings::money($order->total) }}</strong></div><p>Cash on Delivery · Payment {{ $order->payment_status }}<br>Order {{ str_replace('_',' ',$order->status) }}</p></div>@endif<p>{{ $order->public_note }}</p><p class="small">This document records the order. It is not proof of payment or a tax invoice unless separately approved by the business.</p></article></body></html>